       border-radius: 14px;
       padding: 14px 18px;
       background: linear-gradient(180deg, var(--accent), var(--accent-strong));
       color: white;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       box-shadow: 0 12px 28px rgba(90, 124, 255, 0.28);
       transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
     }

     button:hover {
       filter: brightness(1.04);
       transform: translateY(-1px);
     }

     button:focus-visible {
       outline: 3px solid rgba(255, 255, 255, 0.2);
       outline-offset: 3px;
     }

     @media (max-width: 480px) {
       .card {
         padding: 22px;
         border-radius: 20px;
       }
     }
   </style>
 </head>
 <body>
   <main>
     <section class="card" aria-labelledby="support-title">
       <h1 id="support-title">Contact support</h1>
       <p class="lead">Send us a message and we&apos;ll get back to you as soon as possible.</p>

       <form action="#" method="post">
         <div class="form-field">
           <label for="full-name">Full name</label>
           <input id="full-name" name="fullName" type="text" autocomplete="name" required>
         </div>

         <div class="form-field">
           <label for="email-address">Email address</label>
           <input id="email-address" name="email" type="email" autocomplete="email" required>
         </div>

         <div class="form-field">
           <label for="phone-number">Phone number</label>
           <input
             id="phone-number"
             name="phone"
             type="tel"
             autocomplete="tel"
             inputmode="tel"
             aria-describedby="phone-help"
             placeholder="(555) 123-4567"
           >
           <p class="helper-text" id="phone-help">Optional. Enter a 10-digit number like (555) 123-4567 or 555-123-4567.</p>
         </div>

         <div class="actions">
           <button type="submit">Send message</button>
         </div>
       </form>
     </section>
   </main>
   <script>
     const phoneInput = document.getElementById('phone-number');

     function formatPhone(value) {
       const digits = value.replace(/\D/g, '').replace(/^1/, '');

       if (digits.length !== 10) {
         return value.trim();
       }

       return `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6)}`;
     }

     phoneInput.addEventListener('blur', () => {
       if (phoneInput.value.trim() !== '') {
         phoneInput.value = formatPhone(phoneInput.value);
       }
     });
   </script>
 </body>
 </html>

